replacements.after:
if (!editor) missingComposerFrames += 1;
if (!editor || !activeTab) {
  const form = document.querySelector<HTMLElement>('[data-chat-composer-form="true"]');
  const retainedEditor = form?.querySelector<HTMLElement>('[data-testid="composer-editor"]');
  const bounds = retainedEditor?.getBoundingClientRect();
  const state = useStore.getState();
  diagnosticFrames.push({
    elapsedMs: performance.now() - startedAt,
    targetId,
    pathname: mounted.router.state.location.pathname,
    activeTab: activeTab?.textContent,
    formPresent: Boolean(form),
    editorPresent: Boolean(retainedEditor),
    contentEditable: retainedEditor?.getAttribute("contenteditable"),
    editorText: retainedEditor?.textContent,
    editorBounds: bounds ? { x: bounds.x, y: bounds.y, width: bounds.width, height: bounds.height } : null,
    editorVisibility: retainedEditor ? getComputedStyle(retainedEditor).visibility : null,
    editorDisplay: retainedEditor ? getComputedStyle(retainedEditor).display : null,
    editorOpacity: retainedEditor ? getComputedStyle(retainedEditor).opacity : null,
    sourceSync: state.threadDetailSyncById?.[THREAD_ID],
    targetSync: state.threadDetailSyncById?.[targetId],
    sourceSession: state.threadSessionById?.[THREAD_ID],
    targetSession: state.threadSessionById?.[targetId],
  });
}
